window.__DN_I18N={"Kişiye Özel · Uçtan Uca Danışmanlık":{"en":"Tailored · End-to-End Advisory","ru":"Индивидуально · Консультирование под ключ","zh":"私人定制 · 全流程咨询","ar":"استشارة مخصّصة · من البداية إلى النهاية"},"Fikirden":{"en":"From idea","ru":"От идеи","zh":"从构想","ar":"من الفكرة"},"tapuya,":{"en":"to title deed,","ru":"до тапу,","zh":"到房产证，","ar":"إلى سند الملكية،"},"veriyle":{"en":"data-driven","ru":"на основе данных —","zh":"以数据","ar":"بالبيانات"},"uçtan":{"en":"end to","ru":"недвижимость","zh":"贯穿","ar":"من"},"uca":{"en":"end","ru":"под","zh":"始终","ar":"البداية إلى النهاية"},"gayrimenkul.":{"en":"real estate.","ru":"ключ.","zh":"的房地产服务。","ar":"في العقار."},"Alım-satımdan kiralamaya, değerlemeden yatırım analizine ve miras/intikale kadar; gayrimenkulünüzün her aşamasında canlı ProX bölge verisiyle konuşan, tek muhataplı ve tam gizlilikli bir danışmanlık.":{"en":"From buying and selling to leasing, from valuation to investment analysis and inheritance transfer; a single-point, fully confidential advisory that speaks with live ProX regional data at every stage of your real estate journey.","ru":"От купли-продажи до аренды, от оценки стоимости до инвестиционного анализа и наследства/оформления наследства — консультирование с единственным контактным лицом и полной конфиденциальностью, опирающееся на живые региональные данные ProX на каждом этапе работы с вашей недвижимостью.","zh":"从买卖到租赁，从估值到投资分析，直至继承与继承过户；在您房地产的每一个阶段，凭借实时 ProX 区域数据发声，提供单一对接人、完全保密的咨询服务。","ar":"من البيع والشراء إلى التأجير، ومن التقييم إلى تحليل الاستثمار وصولاً إلى الإرث ونقل الإرث؛ استشارة بمُخاطَب واحد وبسرّية تامة، تتحدث بلغة بيانات ProX المنطقية الحية في كل مرحلة من مراحل عقارك."},"Ücretsiz Değer Analizi":{"en":"Free Value Analysis","ru":"Бесплатный анализ стоимости","zh":"免费价值分析","ar":"تحليل قيمة مجاني"},"Tüm Hizmetler":{"en":"All Services","ru":"Все услуги","zh":"全部服务","ar":"جميع الخدمات"},"Uzmanlık Alanı":{"en":"Areas of Expertise","ru":"Область экспертизы","zh":"专业领域","ar":"مجال الاختصاص"},"Yıl Deneyim":{"en":"Years of Experience","ru":"лет опыта","zh":"年经验","ar":"سنة خبرة"},"Veri Odaklı Süreç":{"en":"Data-Driven Process","ru":"Процесс на основе данных","zh":"数据驱动流程","ar":"عملية قائمة على البيانات"},"ProX · Canlı Hizmet Zekâsı":{"en":"ProX · Live Service Intelligence","ru":"ProX · Живая аналитика услуг","zh":"ProX · 实时服务智能","ar":"ProX · ذكاء الخدمة الحي"},"Ort. m²":{"en":"Avg. m²","ru":"Ср. м²","zh":"每平方米均价","ar":"متوسط م²"},"182K ₺":{"en":"182K ₺","ru":"182K ₺","zh":"182K ₺","ar":"182K ₺"},"Yıllık":{"en":"Annual","ru":"Годовой","zh":"年度","ar":"سنوياً"},"Skor":{"en":"Score","ru":"Балл","zh":"评分","ar":"التقييم"},"Likidite":{"en":"Liquidity","ru":"Ликвидность","zh":"流动性","ar":"السيولة"},"Yüksek":{"en":"High","ru":"Высокая","zh":"高","ar":"مرتفعة"},"Hizmet Haritası":{"en":"Service Map","ru":"Карта услуг","zh":"服务地图","ar":"خريطة الخدمات"},"Gayrimenkulün her ihtiyacı için tek bir isim":{"en":"A single name for every real estate need","ru":"Одно имя для любой потребности в недвижимости","zh":"房地产的每一项需求，只需一个名字","ar":"اسم واحد لكل احتياجات العقار"},"Her hizmet, canlı ProX bölge verisi ve 18 yılı aşkın saha deneyimiyle; kişiye özel, tek muhataplı ve kusursuz temsille sunulur.":{"en":"Every service is delivered with live ProX regional data and over 18 years of field experience; tailored, single-point, and impeccably represented.","ru":"Каждая услуга оказывается на основе живых региональных данных ProX и более чем 18-летнего практического опыта — индивидуально, с единственным контактным лицом и безупречным представительством.","zh":"每项服务均依托实时 ProX 区域数据与逾 18 年的实地经验，以私人定制、单一对接人及无懈可击的代理呈现。","ar":"تُقدَّم كل خدمة ببيانات ProX المنطقية الحية وخبرة ميدانية تتجاوز 18 عاماً؛ بشكل مخصّص، وبمُخاطَب واحد، وبتمثيل لا تشوبه شائبة."},"Konut Alım & Satım Danışmanlığı":{"en":"Residential Buying & Selling Advisory","ru":"Консультирование по купле-продаже жилья","zh":"住宅买卖咨询","ar":"استشارة بيع وشراء المساكن"},"Doğru fiyat, doğru zaman ve doğru alıcıyla; lüks konutunuzu güvenle ve gizlilikle alıp satın.":{"en":"Buy and sell your luxury residence with confidence and discretion — at the right price, the right time, and with the right buyer.","ru":"Покупайте и продавайте вашу элитную недвижимость надёжно и конфиденциально — по правильной цене, в правильное время и с правильным покупателем.","zh":"以合适的价格、恰当的时机与合适的买家，安心且保密地买卖您的豪华住宅。","ar":"بالسعر المناسب والوقت المناسب والمشتري المناسب؛ اشترِ وبِع سكنك الفاخر بثقة وسرّية."},"İncele →":{"en":"Explore →","ru":"Подробнее →","zh":"查看 →","ar":"استعرِض →"},"Kiralama & Kira Garantili Yönetim":{"en":"Leasing & Rent-Guaranteed Management","ru":"Аренда и управление с гарантией арендной платы","zh":"租赁与租金保障管理","ar":"التأجير والإدارة مع ضمان الإيجار"},"Kiracı ön elemesinden tahliyeye, kira takibinden garantili gelire kadar tüm süreç bende.":{"en":"From tenant pre-screening to eviction, from rent tracking to guaranteed income — the entire process rests with me.","ru":"Весь процесс на мне — от предварительного отбора арендаторов до выселения, от контроля арендных платежей до гарантированного дохода.","zh":"从租客初审到清退，从租金跟踪到保障收益，全流程由我负责。","ar":"من الفرز المسبق للمستأجر إلى الإخلاء، ومن متابعة الإيجار إلى الدخل المضمون، العملية كاملةً على عاتقي."},"Ticari & Ofis Gayrimenkul":{"en":"Commercial & Office Real Estate","ru":"Коммерческая и офисная недвижимость","zh":"商业与办公房地产","ar":"العقارات التجارية والمكتبية"},"Lokasyon zekâsı ve doğru kiracı eşleştirmesiyle dükkan, ofis ve plaza getirinizi maksimize edin.":{"en":"Maximize the return on your shop, office, or plaza with location intelligence and the right tenant match.","ru":"Максимизируйте доходность магазинов, офисов и бизнес-центров с помощью аналитики локаций и правильного подбора арендаторов.","zh":"凭借选址智能与精准的租客匹配，最大化您的商铺、办公与商业中心收益。","ar":"عظِّم عائد متجرك ومكتبك والمجمّع التجاري بذكاء الموقع والمطابقة الصحيحة للمستأجر."},"Arsa & Arazi Danışmanlığı":{"en":"Land & Plot Advisory","ru":"Консультирование по земельным участкам","zh":"土地咨询","ar":"استشارة الأراضي والقطع"},"İmar, tapu ve zemin risklerini önceden çözerek arsanın gerçek yatırım potansiyelini görün.":{"en":"See the true investment potential of a plot by resolving zoning, title deed, and ground risks in advance.","ru":"Увидьте реальный инвестиционный потенциал участка, заранее устранив риски зонирования, тапу и грунта.","zh":"提前化解规划、房产证与地质风险，洞见土地真正的投资潜力。","ar":"شاهِد إمكانات الأرض الاستثمارية الحقيقية بحلّ مخاطر التخطيط العمراني وسند الملكية والتربة مسبقاً."},"Değerleme & Ön Ekspertiz":{"en":"Valuation & Preliminary Appraisal","ru":"Оценка стоимости и предварительная оценка","zh":"估值与初步估价","ar":"التقييم والتقييم العقاري المبدئي"},"Emsal verisiyle gerçek piyasa değerini belirler, resmi işlemler için SPK lisanslı ekspertize yönlendiririm.":{"en":"I determine the true market value using comparable data, and refer you to SPK-licensed appraisal for official transactions.","ru":"Определяю реальную рыночную стоимость на основе данных по аналогам и направляю к лицензированной SPK оценке для официальных процедур.","zh":"凭借可比案例数据确定真实市场价值，并为正式手续引荐至 SPK 持牌估价机构。","ar":"أحدّد القيمة السوقية الحقيقية ببيانات المقارنة، وأوجّهك إلى تقييم عقاري مرخّص من SPK للمعاملات الرسمية."},"Yatırım Danışmanlığı & Getiri Analizi":{"en":"Investment Advisory & Return Analysis","ru":"Инвестиционное консультирование и анализ доходности","zh":"投资咨询与收益分析","ar":"استشارة الاستثمار وتحليل العائد"},"Kira çarpanı, net ROI ve amortisman süresiyle; duygusal değil veri odaklı yatırım kararları.":{"en":"Investment decisions driven by data, not emotion — with rent multiplier, net ROI, and payback period.","ru":"Инвестиционные решения на основе данных, а не эмоций — с учётом арендного мультипликатора, чистого ROI и срока окупаемости.","zh":"凭借租金倍数、净投资回报率与回本周期，做出数据驱动而非感性的投资决策。","ar":"قرارات استثمارية قائمة على البيانات لا على العاطفة؛ بمضاعف الإيجار وصافي العائد على الاستثمار وفترة الاسترداد."},"Bölge & Fiyat Endeksi Analizi":{"en":"Region & Price Index Analysis","ru":"Анализ региона и ценового индекса","zh":"区域与价格指数分析","ar":"تحليل مؤشر المنطقة والأسعار"},"Canlı ProX m² endeksi ve mahalle bazlı verilerle hangi bölgenin ne zaman değerlendiğini gösteririm.":{"en":"With the live ProX m² index and neighborhood-level data, I show which area is appreciating and when.","ru":"На основе живого индекса ProX за м² и данных по районам показываю, какой район и когда растёт в цене.","zh":"凭借实时 ProX 每平方米指数与按社区划分的数据，为您呈现哪个区域何时增值。","ar":"أُظهِر لك أيّ منطقة ترتفع قيمتها ومتى، بمؤشر ProX الحي لسعر المتر المربع وبيانات على مستوى الأحياء."},"Tapu & Hukuki Süreç":{"en":"Title Deed & Legal Process","ru":"Тапу и юридический процесс","zh":"房产证与法律流程","ar":"سند الملكية والإجراءات القانونية"},"Web Tapu başvurusundan harç ödemesine ve devir randevusuna kadar tüm tapu sürecini hatasız yönetirim.":{"en":"I manage the entire title deed process flawlessly — from the Web Tapu application to fee payment and the transfer appointment.","ru":"Безошибочно веду весь процесс оформления тапу — от заявки в «Web Tapu» до уплаты пошлины и записи на переоформление.","zh":"从 \"Web Tapu\" 申请到税费缴纳及过户预约，无差错地管理整个房产证流程。","ar":"أُدير عملية سند الملكية كاملةً دون خطأ، من طلب \"Web Tapu\" إلى دفع الرسوم وموعد نقل الملكية."},"Konut Kredisi & Ödeme Planı":{"en":"Mortgage & Payment Plan","ru":"Ипотека и план платежей","zh":"住房贷款与还款计划","ar":"قرض السكن وخطة السداد"},"Ekspertiz, faiz ve ödeme planını karşılaştırarak en uygun kredi yapısını kurgular, süreci hızlandırırım.":{"en":"By comparing appraisal, interest rates, and payment plans, I structure the most suitable loan and accelerate the process.","ru":"Сравнивая оценку, процентные ставки и планы платежей, выстраиваю наиболее выгодную структуру кредита и ускоряю процесс.","zh":"通过比较估价、利率与还款计划，构建最优贷款方案并加快流程。","ar":"أُصمّم البنية الائتمانية الأنسب بمقارنة التقييم العقاري والفائدة وخطة السداد، وأُسرّع العملية."},"Portföy Yönetimi":{"en":"Portfolio Management","ru":"Управление портфелем","zh":"投资组合管理","ar":"إدارة المحفظة"},"Birden fazla gayrimenkulün kira, bakım, vergi ve değer takibini tek elden yöneterek getiriyi optimize ederim.":{"en":"I optimize returns by managing the rent, maintenance, tax, and value tracking of multiple properties from a single point.","ru":"Оптимизирую доходность, управляя из одних рук арендой, обслуживанием, налогами и отслеживанием стоимости нескольких объектов недвижимости.","zh":"统一管理多处房产的租金、维护、税务与价值跟踪，优化收益。","ar":"أُحسّن العائد بإدارة إيجار عدة عقارات وصيانتها وضرائبها ومتابعة قيمتها من جهة واحدة."},"Home Staging & Satışa Hazırlık":{"en":"Home Staging & Sale Preparation","ru":"Хоум-стейджинг и подготовка к продаже","zh":"房屋美化与售前准备","ar":"تهيئة المنزل للبيع والإعداد للبيع"},"Profesyonel sunum, görsel ve düzenlemeyle gayrimenkulünüzü daha hızlı ve daha yüksek fiyata satılır hale getiririm.":{"en":"With professional presentation, imagery, and styling, I make your property sell faster and at a higher price.","ru":"С помощью профессиональной презентации, фотографий и оформления делаю вашу недвижимость продаваемой быстрее и по более высокой цене.","zh":"凭借专业展示、影像与布置，让您的房产更快、以更高价格售出。","ar":"أجعل عقارك قابلاً للبيع بشكل أسرع وبسعر أعلى من خلال العرض الاحترافي والصور والتنسيق."},"Kentsel Dönüşüm & Yeni Proje":{"en":"Urban Transformation & New Development","ru":"Городская трансформация и новый проект","zh":"城市更新与新项目","ar":"التحول العمراني والمشاريع الجديدة"},"Riskli yapı tespitinden hak sahipliğine ve devlet desteklerine kadar dönüşüm sürecinizde yanınızdayım.":{"en":"I stand by you throughout the transformation process — from risk-bearing building assessment to entitlement rights and state incentives.","ru":"Я рядом с вами на всём пути реновации — от признания здания аварийным до установления прав собственников и получения государственной поддержки.","zh":"从危房认定到权属确认及政府补贴，在您的更新流程中始终相伴。","ar":"أقف إلى جانبك في عملية التحول، من تحديد المبنى المعرّض للخطر إلى استحقاق الحقوق والدعم الحكومي."},"Yabancıya Satış & Oturma İzni":{"en":"Sale to Foreigners & Residence Permit","ru":"Продажа иностранцам и ВНЖ","zh":"面向外籍人士销售与居留许可","ar":"البيع للأجانب وتصريح الإقامة"},"Döviz bozdurma belgesinden vatandaşlık başvurusuna kadar yabancı yatırımcıya uyumlu, uçtan uca süreç.":{"en":"An end-to-end process tailored to the foreign investor — from the currency exchange certificate to the citizenship application.","ru":"Процесс под ключ, адаптированный для иностранного инвестора — от справки об обмене валюты до заявления на гражданство.","zh":"从外汇兑换证明到公民身份申请，为外籍投资者量身打造的全流程服务。","ar":"عملية متكاملة من البداية إلى النهاية، متوافقة مع المستثمر الأجنبي، من شهادة صرف العملة إلى طلب الجنسية."},"Boğaz & Yalı · Özel Segment":{"en":"Bosphorus & Yalı · Exclusive Segment","ru":"Босфор и ялы · Особый сегмент","zh":"博斯普鲁斯与博斯普鲁斯海滨豪宅 · 高端专属","ar":"البوسفور والقصور المائية · الشريحة الخاصة"},"Boğaz hattı yalı, penthouse ve özel segment gayrimenkullerde davet usulü, tam gizlilikli temsil ve prim yönetimi.":{"en":"By-invitation, fully confidential representation and appreciation management for Bosphorus-line waterfront mansions (yalı), penthouses, and exclusive-segment properties.","ru":"Продажи по приглашению, полностью конфиденциальное представительство и управление приростом стоимости для ялы на Босфоре, пентхаусов и объектов особого сегмента.","zh":"在博斯普鲁斯沿岸海滨豪宅、顶层公寓及高端专属房产领域，提供邀请制、完全保密的代理与增值管理。","ar":"تمثيل بالدعوة وبسرّية تامة وإدارة ارتفاع القيمة في قصور البوسفور المائية والبنتهاوس والعقارات ذات الشريحة الخاصة."},"Miras & İntikal İşlemleri":{"en":"Inheritance & Transfer Procedures","ru":"Наследство и оформление наследства","zh":"继承与继承过户事务","ar":"معاملات الإرث ونقل الإرث"},"Veraset ilamından tapu intikaline, reddi mirastan izale-i şuyuya kadar tüm süreç tek elden.":{"en":"The entire process from a single point — from the certificate of inheritance to title deed transfer, from disclaimer of inheritance to partition of co-ownership.","ru":"Весь процесс из одних рук — от свидетельства о наследстве до оформления наследства на тапу, от отказа от наследства до раздела общей собственности.","zh":"从继承裁定书到房产证继承过户，从放弃继承到共有物分割，全流程一站式办理。","ar":"العملية كاملةً من جهة واحدة، من حجّة الوراثة إلى نقل سند الملكية، ومن ردّ الإرث إلى قسمة المال الشائع."},"Rehberi Aç →":{"en":"Open the Guide →","ru":"Открыть гид →","zh":"打开指南 →","ar":"افتح الدليل →"},"Neden Selin Meridyen?":{"en":"Why Selin Meridyen?","ru":"Почему Selin Meridyen?","zh":"为何选择 Selin Meridyen？","ar":"لماذا Selin Meridyen؟"},"Aynı hizmet değil;":{"en":"Not the same service;","ru":"Не та же услуга —","zh":"并非千篇一律的服务；","ar":"ليست الخدمة نفسها؛"},"veriyle güçlendirilmiş":{"en":"data-powered","ru":"консультирование,","zh":"而是由数据赋能的","ar":"استشارة"},"danışmanlık.":{"en":"advisory.","ru":"усиленное данными.","zh":"咨询。","ar":"معزّزة بالبيانات."},"Geleneksel emlakçılık tahmine dayanır; benim yaklaşımım canlı ProX bölge verisine, tam gizliliğe ve tek muhataplı temsile dayanır. Fark, sonuçta ortaya çıkar.":{"en":"Traditional real estate rests on guesswork; my approach rests on live ProX regional data, full confidentiality, and single-point representation. The difference shows in the outcome.","ru":"Традиционная риелторская работа строится на догадках — мой подход опирается на живые региональные данные ProX, полную конфиденциальность и представительство с единственным контактным лицом. Разница видна в результате.","zh":"传统房产中介依赖臆测；而我的方式建立在实时 ProX 区域数据、完全保密与单一对接人代理之上。差别，终将体现于结果。","ar":"تقوم الوساطة العقارية التقليدية على التخمين؛ أما نهجي فيقوم على بيانات ProX المنطقية الحية والسرّية التامة والتمثيل بمُخاطَب واحد. الفرق يظهر في النتيجة."},"Canlı ProX Verisi":{"en":"Live ProX Data","ru":"Живые данные ProX","zh":"实时 ProX 数据","ar":"بيانات ProX الحية"},"Her karar mahalle bazlı m² endeksi, yıllık değişim ve yatırım skoruyla desteklenir — tahminle değil rakamla.":{"en":"Every decision is backed by the neighborhood-level m² index, annual change, and investment score — by numbers, not guesses.","ru":"Каждое решение подкреплено индексом за м² по районам, годовым изменением и инвестиционным баллом — цифрами, а не догадками.","zh":"每一项决策均由按社区划分的每平方米指数、年度变化与投资评分支撑——以数字而非臆测为据。","ar":"كل قرار مدعوم بمؤشر سعر المتر المربع على مستوى الحي والتغيّر السنوي وتقييم الاستثمار — بالأرقام لا بالتخمين."},"Tam Gizlilik":{"en":"Full Confidentiality","ru":"Полная конфиденциальность","zh":"完全保密","ar":"سرّية تامة"},"Adres ve kimlik mahremiyeti esas; davet usulü satışta detaylar yalnızca ciddi alıcıyla, onayınızla açılır.":{"en":"Address and identity privacy is paramount; in by-invitation sales, details are disclosed only to serious buyers, with your consent.","ru":"Конфиденциальность адреса и личности — основа; при продаже по приглашению детали раскрываются только серьёзному покупателю и с вашего согласия.","zh":"地址与身份隐私为本；在邀请制销售中，细节仅在您授权后向诚意买家披露。","ar":"خصوصية العنوان والهوية أساس؛ في البيع بالدعوة، لا تُكشَف التفاصيل إلا للمشتري الجادّ وبموافقتك."},"Tek Muhatap":{"en":"Single Point of Contact","ru":"Единственное контактное лицо","zh":"单一对接人","ar":"مُخاطَب واحد"},"Baştan sona aynı isim: tutarlı mesaj, kontrollü süreç ve size özel, kesintisiz iletişim.":{"en":"The same name from start to finish: a consistent message, a controlled process, and dedicated, uninterrupted communication.","ru":"От начала до конца одно имя: последовательная коммуникация, контролируемый процесс и персональное, непрерывное общение.","zh":"自始至终同一个人：一致的信息、可控的流程与专属您的不间断沟通。","ar":"الاسم نفسه من البداية إلى النهاية: رسالة متّسقة، وعملية مضبوطة، وتواصل مخصّص لك دون انقطاع."},"EİDS Yetki Belgeli":{"en":"EİDS Authorization Certificate","ru":"С разрешением EİDS","zh":"持 EİDS 授权证书","ar":"حاصلة على شهادة تفويض EİDS"},"e-Devlet doğrulamalı yetki belgesiyle; resmî, güvenli ve mevzuata tam uyumlu bir temsil.":{"en":"Representation that is official, secure, and fully compliant — with an e-Devlet-verified authorization certificate.","ru":"С разрешением, подтверждённым через e-Devlet — официальное, надёжное и полностью соответствующее законодательству представительство.","zh":"凭借经 e-Devlet 验证的授权证书，提供正规、安全且完全合规的代理。","ar":"تمثيل رسمي وآمن ومتوافق تماماً مع التشريعات، بشهادة تفويض موثّقة عبر e-Devlet."},"Kusursuz Müzakere":{"en":"Impeccable Negotiation","ru":"Безупречные переговоры","zh":"无懈可击的谈判","ar":"تفاوض لا تشوبه شائبة"},"Teklifleri değerinizi koruyacak şekilde yürütür; doğru zaman ve doğru fiyatı stratejiyle savunurum.":{"en":"I handle offers in a way that protects your value, defending the right time and the right price with strategy.","ru":"Веду переговоры по предложениям так, чтобы защитить вашу стоимость — стратегически отстаиваю правильное время и правильную цену.","zh":"以维护您价值的方式推进报价；以策略捍卫恰当的时机与合适的价格。","ar":"أُدير العروض بما يحمي قيمتك؛ وأُدافع عن الوقت المناسب والسعر المناسب باستراتيجية."},"18+ Yıl Saha Deneyimi":{"en":"18+ Years of Field Experience","ru":"18+ лет практического опыта","zh":"18+ 年实地经验","ar":"أكثر من 18 عاماً من الخبرة الميدانية"},"Boğaz hattı, Nişantaşı ve Bağdat Caddesi'nde yılların oluşturduğu güçlü alıcı ağı ve yerel hakimiyet.":{"en":"A strong buyer network and local command built over years along the Bosphorus, in Nişantaşı, and on Bağdat Caddesi.","ru":"Сильная сеть покупателей и знание местного рынка, наработанные за годы на Босфоре, в Nişantaşı и на Bağdat Caddesi.","zh":"在博斯普鲁斯沿岸、Nişantaşı 与 Bağdat Caddesi 多年积淀的强大买家网络与本地主导优势。","ar":"شبكة مشترين قوية وإلمام محلي بنَتهما السنون على خط البوسفور وNişantaşı وBağdat Caddesi."},"Alım & Satım":{"en":"Buying & Selling","ru":"Купля-продажа","zh":"买卖","ar":"البيع والشراء"},"Konutunuzu doğru fiyatla, doğru alıcıyla ve tam gizlilikle buluştururum.":{"en":"I match your residence with the right price, the right buyer, and full confidentiality.","ru":"Свожу ваше жильё с правильным покупателем — по правильной цене и с полной конфиденциальностью.","zh":"以合适的价格、合适的买家与完全的保密，为您的住宅牵线。","ar":"أجمع سكنك بالسعر المناسب والمشتري المناسب وبسرّية تامة."},"Değeri bir rakamla başlatmam; önce gayrimenkulün konumunu, eşsiz niteliklerini ve canlı ProX bölge verisini analiz ederim. Açık ilan mı yoksa davet usulü gizli pazarlama mı — gayrimenkulün niteliğine göre doğru kanalı seçer, tüm müzakereyi tek muhatap olarak değerinizi koruyarak yürütürüm.":{"en":"I don't start value with a number; first I analyze the property's location, its unique qualities, and live ProX regional data. Open listing or by-invitation discreet marketing — I choose the right channel according to the property's character and conduct the entire negotiation as your single point of contact, protecting your value.","ru":"Я не начинаю со случайной цифры — сначала анализирую расположение объекта, его уникальные качества и живые региональные данные ProX. Открытое объявление или закрытая продажа по приглашению — выбираю правильный канал в зависимости от характера объекта и веду все переговоры как единственное контактное лицо, защищая вашу стоимость.","zh":"我不会以一个数字为起点；而是先分析房产的区位、独特品质与实时 ProX 区域数据。公开挂牌还是邀请制隐秘营销——依据房产的属性选择正确的渠道，并作为单一对接人贯穿全程谈判，维护您的价值。","ar":"لا أبدأ القيمة برقم؛ بل أُحلّل أولاً موقع العقار وخصائصه الفريدة وبيانات ProX المنطقية الحية. إعلان علني أم تسويق سرّي بالدعوة — أختار القناة الصحيحة وفق طبيعة العقار، وأُدير التفاوض كاملاً كمُخاطَب واحد يحمي قيمتك."},"İhtiyaç & beklenti analizi":{"en":"Needs & expectations analysis","ru":"Анализ потребностей и ожиданий","zh":"需求与期望分析","ar":"تحليل الاحتياجات والتوقّعات"},"ProX emsal veri ile doğru fiyatlandırma":{"en":"Accurate pricing with ProX comparable data","ru":"Правильное ценообразование по данным аналогов ProX","zh":"凭借 ProX 可比案例数据精准定价","ar":"تسعير صحيح ببيانات المقارنة من ProX"},"Konumlandırma & profesyonel sunum":{"en":"Positioning & professional presentation","ru":"Позиционирование и профессиональная презентация","zh":"定位与专业展示","ar":"التموضع والعرض الاحترافي"},"Nitelikli alıcı & müzakere":{"en":"Qualified buyer & negotiation","ru":"Квалифицированный покупатель и переговоры","zh":"优质买家与谈判","ar":"مشترٍ مؤهّل وتفاوض"},"Sözleşme ve kusursuz tapu devri":{"en":"Contract and flawless title deed transfer","ru":"Договор и безупречное переоформление тапу","zh":"合同与无差错房产证过户","ar":"عقد ونقل سند ملكية لا تشوبه شائبة"},"Tam gizlilik":{"en":"Full confidentiality","ru":"Полная конфиденциальность","zh":"完全保密","ar":"سرّية تامة"},"Veri odaklı fiyat":{"en":"Data-driven price","ru":"Цена на основе данных","zh":"数据驱动定价","ar":"سعر قائم على البيانات"},"Tek muhatap":{"en":"Single point of contact","ru":"Единственное контактное лицо","zh":"单一对接人","ar":"مُخاطَب واحد"},"Evimin gerçek değerini nasıl belirliyorsunuz?":{"en":"How do you determine my home's true value?","ru":"Как вы определяете реальную стоимость моего дома?","zh":"您如何确定我房屋的真实价值？","ar":"كيف تحدّدون القيمة الحقيقية لمنزلي؟"},"Yerinde inceleme, benzer satışların emsal verisi ve canlı ProX mahalle m² endeksiyle bir değer aralığı çıkarır; resmi işlem gerekiyorsa SPK lisanslı ekspertize yönlendiririm.":{"en":"I produce a value range through an on-site inspection, comparable data from similar sales, and the live ProX neighborhood m² index; if an official transaction is required, I refer you to SPK-licensed appraisal.","ru":"На основе осмотра на месте, данных по аналогичным продажам и живого индекса ProX за м² по району вывожу диапазон стоимости; если требуется официальная процедура — направляю к лицензированной SPK оценке.","zh":"通过实地勘察、同类成交的可比案例数据与实时 ProX 社区每平方米指数，得出一个价值区间；若需正式手续，则引荐至 SPK 持牌估价机构。","ar":"أستخرج نطاق قيمة عبر المعاينة الميدانية وبيانات مقارنة المبيعات المماثلة ومؤشر ProX الحي لسعر المتر المربع في الحي؛ وإن لزمت معاملة رسمية أوجّهك إلى تقييم عقاري مرخّص من SPK."},"Kiralama":{"en":"Leasing","ru":"Аренда","zh":"租赁","ar":"التأجير"},"Kiracı bulmadan tahliyeye kadar tüm süreci risksiz yönetirim.":{"en":"I manage the entire process risk-free, from finding a tenant to eviction.","ru":"Веду весь процесс без рисков — от поиска арендатора до выселения.","zh":"从寻找租客到清退，无风险地管理整个流程。","ar":"أُدير العملية كاملةً دون مخاطر، من إيجاد المستأجر إلى الإخلاء."},"Kiracıyı gelir ve referans üzerinden ön eleme yapar, tahliye taahhütnamesi ve demirbaş tutanaklarıyla gayrimenkulünüzü güvence altına alırım. İsterseniz kira garantili yönetim modeliyle geliriniz düzenli, gayrimenkulünüz bakımlı kalır.":{"en":"I pre-screen tenants by income and references, and secure your property with an eviction undertaking and fixture inventories. If you wish, with the rent-guaranteed management model your income stays regular and your property well-maintained.","ru":"Провожу предварительный отбор арендатора по доходу и рекомендациям, защищаю вашу недвижимость обязательством о выселении и актами инвентаризации имущества. При желании по модели управления с гарантией арендной платы ваш доход остаётся регулярным, а недвижимость — ухоженной.","zh":"通过收入与推荐资料对租客进行初审，凭借清退承诺书与固定资产清单为您的房产保驾护航。如您愿意，以租金保障管理模式，让您的收入稳定、房产得以妥善维护。","ar":"أُجري فرزاً مسبقاً للمستأجر عبر الدخل والمراجع، وأُؤمّن عقارك بتعهّد الإخلاء ومحاضر المنقولات. وإن رغبت، يبقى دخلك منتظماً وعقارك مصاناً بنموذج الإدارة مع ضمان الإيجار."},"Doğru kira bedeli tespiti (ProX)":{"en":"Determining the right rental price (ProX)","ru":"Определение правильной арендной ставки (ProX)","zh":"确定合理租金（ProX）","ar":"تحديد بدل الإيجار الصحيح (ProX)"},"Kiracı ön eleme: gelir & referans":{"en":"Tenant pre-screening: income & references","ru":"Предварительный отбор арендатора: доход и рекомендации","zh":"租客初审：收入与推荐资料","ar":"الفرز المسبق للمستأجر: الدخل والمراجع"},"Sözleşme, taahhütname & demirbaş":{"en":"Contract, undertaking & fixtures","ru":"Договор, обязательство и опись имущества","zh":"合同、承诺书与固定资产","ar":"العقد والتعهّد والمنقولات"},"Kira takibi & tahsilat":{"en":"Rent tracking & collection","ru":"Контроль арендных платежей и взыскание","zh":"租金跟踪与收缴","ar":"متابعة الإيجار والتحصيل"},"Bakım, denetim ve tahliye yönetimi":{"en":"Maintenance, inspection, and eviction management","ru":"Обслуживание, контроль и управление выселением","zh":"维护、检查与清退管理","ar":"إدارة الصيانة والتفتيش والإخلاء"},"Kiracı ön eleme":{"en":"Tenant pre-screening","ru":"Предварительный отбор арендатора","zh":"租客初审","ar":"الفرز المسبق للمستأجر"},"Garantili gelir opsiyonu":{"en":"Guaranteed income option","ru":"Опция гарантированного дохода","zh":"保障收益选项","ar":"خيار الدخل المضمون"},"Kira garantisi nasıl çalışıyor?":{"en":"How does the rent guarantee work?","ru":"Как работает гарантия арендной платы?","zh":"租金保障如何运作？","ar":"كيف يعمل ضمان الإيجار؟"},"Anlaşmalı modelde, kiracı ödemesinden bağımsız olarak kira geliriniz düzenli ödenir; kiracı bulma, takip ve olası tahliye süreçlerini ben üstlenirim.":{"en":"Under the agreed model, your rental income is paid regularly regardless of the tenant's payment; I take on the tenant sourcing, tracking, and any eviction processes.","ru":"По договорной модели ваш арендный доход выплачивается регулярно независимо от платежей арендатора; поиск арендатора, контроль и возможное выселение беру на себя.","zh":"在约定模式下，无论租客是否付款，您的租金收入都会按时支付；寻找租客、跟踪及可能的清退流程均由我承担。","ar":"في النموذج التعاقدي، يُدفع دخل إيجارك بانتظام بصرف النظر عن سداد المستأجر؛ وأتولّى بنفسي عمليات إيجاد المستأجر والمتابعة والإخلاء المحتمل."},"Ticari & Ofis":{"en":"Commercial & Office","ru":"Коммерческая и офисная","zh":"商业与办公","ar":"التجاري والمكتبي"},"Ticari & Ofis Gayrimenkul Danışmanlığı":{"en":"Commercial & Office Real Estate Advisory","ru":"Консультирование по коммерческой и офисной недвижимости","zh":"商业与办公房地产咨询","ar":"استشارة العقارات التجارية والمكتبية"},"Lokasyon zekâsı ve doğru kiracıyla ticari getirinizi maksimize ederim.":{"en":"I maximize your commercial return with location intelligence and the right tenant.","ru":"Максимизирую вашу коммерческую доходность с помощью аналитики локаций и правильного арендатора.","zh":"凭借选址智能与合适的租客，最大化您的商业收益。","ar":"أُعظّم عائدك التجاري بذكاء الموقع والمستأجر المناسب."},"Dükkan, ofis, plaza ve depo yatırımlarında yaya akımı, demografik segmentasyon ve emsal kira verisiyle konumu değerlendirir; kurumsal kiracı eşleştirmesiyle boşluk süresini kısaltır, getiriyi yükseltirim.":{"en":"For shop, office, plaza, and warehouse investments, I assess the location with foot traffic, demographic segmentation, and comparable rent data; through corporate tenant matching, I shorten vacancy periods and raise returns.","ru":"В инвестициях в магазины, офисы, бизнес-центры и склады оцениваю локацию по пешеходному трафику, демографической сегментации и данным по аренде аналогов; подбором корпоративных арендаторов сокращаю простой и повышаю доходность.","zh":"在商铺、办公、商业中心与仓库投资中，凭借人流量、人口结构细分与可比租金数据评估选址；通过机构租客匹配缩短空置期、提升收益。","ar":"أُقيّم الموقع في استثمارات المتاجر والمكاتب والمجمّعات التجارية والمستودعات عبر حركة المارّة والتقسيم الديموغرافي وبيانات الإيجار المقارِنة؛ وأُقصّر مدة الشغور وأرفع العائد بمطابقة المستأجر المؤسسي."},"Lokasyon & yaya akımı analizi":{"en":"Location & foot-traffic analysis","ru":"Анализ локации и пешеходного трафика","zh":"选址与人流量分析","ar":"تحليل الموقع وحركة المارّة"},"Emsal kira & getiri kıyaslaması":{"en":"Comparable rent & return benchmarking","ru":"Сравнение аренды аналогов и доходности","zh":"可比租金与收益对比","ar":"مقارنة الإيجار المماثل والعائد"},"Kurumsal kiracı eşleştirme":{"en":"Corporate tenant matching","ru":"Подбор корпоративных арендаторов","zh":"机构租客匹配","ar":"مطابقة المستأجر المؤسسي"},"Kira sözleşmesi & şartname":{"en":"Lease agreement & specifications","ru":"Договор аренды и техническое задание","zh":"租赁合同与条款说明","ar":"عقد الإيجار وكرّاس الشروط"},"Lokasyon zekâsı":{"en":"Location intelligence","ru":"Аналитика локации","zh":"选址智能","ar":"ذكاء الموقع"},"Kurumsal kiracı ağı":{"en":"Corporate tenant network","ru":"Сеть корпоративных арендаторов","zh":"机构租客网络","ar":"شبكة المستأجرين المؤسسيين"},"Ofis mi dükkan mı daha iyi yatırım?":{"en":"Which is the better investment — office or shop?","ru":"Что выгоднее для инвестиций — офис или магазин?","zh":"办公还是商铺更值得投资？","ar":"أيّهما استثمار أفضل: المكتب أم المتجر؟"},"Bütçe, risk toleransı ve bölgeye göre değişir; ProX getiri verisiyle her iki senaryonun net ROI ve amortisman süresini karşılaştırıp size uygun olanı öneririm.":{"en":"It depends on budget, risk tolerance, and location; using ProX return data, I compare the net ROI and payback period of both scenarios and recommend the one that suits you.","ru":"Это зависит от бюджета, толерантности к риску и района; на основе данных о доходности ProX сравниваю чистый ROI и срок окупаемости обоих сценариев и рекомендую подходящий вам.","zh":"视预算、风险承受力与区域而定；凭借 ProX 收益数据比较两种方案的净投资回报率与回本周期，为您推荐最合适者。","ar":"يختلف الأمر بحسب الميزانية وتحمّل المخاطر والمنطقة؛ أُقارن صافي العائد على الاستثمار وفترة الاسترداد للسيناريوهين ببيانات عائد ProX وأقترح ما يناسبك."},"Arsa & Arazi":{"en":"Land & Plot","ru":"Земельные участки","zh":"土地","ar":"الأراضي والقطع"},"İmar ve tapu risklerini önceden çözerek gerçek potansiyeli ortaya çıkarırım.":{"en":"I reveal the true potential by resolving zoning and title deed risks in advance.","ru":"Раскрываю реальный потенциал, заранее устраняя риски зонирования и тапу.","zh":"提前化解规划与房产证风险，揭示真正的潜力。","ar":"أُظهِر الإمكانات الحقيقية بحلّ مخاطر التخطيط العمراني وسند الملكية مسبقاً."},"Tapu niteliği, imar durumu, hisse/şufa ve zemin-fay risklerini satın almadan önce netleştiririm. Gelişim koridorlarını ve imar planı beklentilerini değerlendirerek arsanın gerçek yatırım değerini gösteririm.":{"en":"I clarify the title deed status, zoning condition, share/pre-emption rights, and ground-fault risks before purchase. By assessing development corridors and zoning plan expectations, I reveal the plot's true investment value.","ru":"До покупки проясняю характер тапу, статус зонирования, риски долевой собственности/преимущественного права и грунта-разломов. Оценивая коридоры развития и ожидания по плану зонирования, показываю реальную инвестиционную стоимость участка.","zh":"在购买前厘清房产证性质、规划状况、份额/优先购买权及地质-断层风险。通过评估发展走廊与规划预期，为您呈现土地真正的投资价值。","ar":"أُوضّح قبل الشراء طبيعة سند الملكية وحالة التخطيط العمراني والحصص/حقّ الشفعة ومخاطر التربة والصدوع. وأُظهِر القيمة الاستثمارية الحقيقية للأرض بتقييم ممرّات التطوير وتوقّعات مخطّط التخطيط العمراني."},"Tapu & imar durumu incelemesi":{"en":"Title deed & zoning status review","ru":"Проверка тапу и статуса зонирования","zh":"房产证与规划状况审查","ar":"فحص سند الملكية وحالة التخطيط العمراني"},"Hisse, şufa ve zemin risk analizi":{"en":"Share, pre-emption right, and ground risk analysis","ru":"Анализ рисков долевой собственности, преимущественного права и грунта","zh":"份额、优先购买权与地质风险分析","ar":"تحليل مخاطر الحصص وحقّ الشفعة والتربة"},"Gelişim koridoru & değer projeksiyonu":{"en":"Development corridor & value projection","ru":"Коридор развития и прогноз стоимости","zh":"发展走廊与价值预测","ar":"ممرّ التطوير وإسقاط القيمة"},"Alım stratejisi & müzakere":{"en":"Acquisition strategy & negotiation","ru":"Стратегия покупки и переговоры","zh":"购买策略与谈判","ar":"استراتيجية الشراء والتفاوض"},"Ön risk denetimi":{"en":"Preliminary risk audit","ru":"Предварительная проверка рисков","zh":"前期风险审查","ar":"التدقيق المسبق للمخاطر"},"İmar okuma":{"en":"Zoning interpretation","ru":"Чтение зонирования","zh":"规划解读","ar":"قراءة التخطيط العمراني"},"İmarsız arsa alınır mı?":{"en":"Should you buy unzoned land?","ru":"Стоит ли покупать участок без зонирования?","zh":"无规划的土地能买吗？","ar":"هل تُشترى الأرض غير المخطَّطة عمرانياً؟"},"Alınabilir ama risk profili farklıdır; imar beklentisi, bölge planları ve süre analizini birlikte değerlendirir, spekülatif değil gerçekçi bir tabloyla karar vermenizi sağlarım.":{"en":"It can be, but the risk profile is different; I evaluate the zoning outlook, regional plans, and timeline analysis together, enabling you to decide on a realistic rather than speculative picture.","ru":"Купить можно, но профиль рисков иной; я совместно оцениваю ожидания по зонированию, региональные планы и анализ сроков, чтобы вы принимали решение на основе реалистичной, а не спекулятивной картины.","zh":"可以买，但风险特征不同；综合评估规划预期、区域规划与周期分析，让您以现实而非投机的图景做出决策。","ar":"يمكن شراؤها لكن ملفّها المخاطري مختلف؛ أُقيّم معاً توقّع التخطيط العمراني وخطط المنطقة وتحليل المدة، وأمكّنك من اتخاذ القرار بصورة واقعية لا تخمينية."},"Değerleme":{"en":"Valuation","ru":"Оценка стоимости","zh":"估值","ar":"التقييم"},"Emsal verisiyle gerçek piyasa değerini, şişirilmiş beklentiler olmadan belirlerim.":{"en":"I determine the true market value with comparable data, free of inflated expectations.","ru":"Определяю реальную рыночную стоимость по данным аналогов, без завышенных ожиданий.","zh":"凭借可比案例数据确定真实市场价值，摒弃虚高的预期。","ar":"أحدّد القيمة السوقية الحقيقية ببيانات المقارنة، دون توقّعات مبالَغ فيها."},"Ücretsiz ön değerlemede canlı ProX mahalle m² endeksi ve benzer satışları temel alırım. Resmi bir rapor gerektiğinde (kredi, dava, miras) sizi SPK lisanslı ekspertize yönlendirir, süreci koordine ederim.":{"en":"For a free preliminary valuation, I base it on the live ProX neighborhood m² index and similar sales. When an official report is required (loan, litigation, inheritance), I refer you to SPK-licensed appraisal and coordinate the process.","ru":"При бесплатной предварительной оценке опираюсь на живой индекс ProX за м² по району и аналогичные продажи. Когда требуется официальный отчёт (кредит, судебное дело, наследство), направляю вас к лицензированной SPK оценке и координирую процесс.","zh":"在免费初步估值中，以实时 ProX 社区每平方米指数与同类成交为依据。当需要正式报告时（贷款、诉讼、继承），我会将您引荐至 SPK 持牌估价机构并协调流程。","ar":"في التقييم المبدئي المجاني أعتمد على مؤشر ProX الحي لسعر المتر المربع في الحي والمبيعات المماثلة. وعند الحاجة إلى تقرير رسمي (قرض، دعوى، إرث) أوجّهك إلى تقييم عقاري مرخّص من SPK وأُنسّق العملية."},"Yerinde inceleme & nitelik tespiti":{"en":"On-site inspection & quality assessment","ru":"Осмотр на месте и определение характеристик","zh":"实地勘察与品质认定","ar":"المعاينة الميدانية وتحديد الخصائص"},"ProX emsal & endeks karşılaştırması":{"en":"ProX comparable & index comparison","ru":"Сравнение аналогов и индекса ProX","zh":"ProX 可比案例与指数比较","ar":"مقارنة المقارنات والمؤشر من ProX"},"Değer aralığı raporu":{"en":"Value range report","ru":"Отчёт о диапазоне стоимости","zh":"价值区间报告","ar":"تقرير نطاق القيمة"},"Gerekirse SPK lisanslı ekspertiz yönlendirmesi":{"en":"SPK-licensed appraisal referral if needed","ru":"При необходимости направление к лицензированной SPK оценке","zh":"如有需要，引荐至 SPK 持牌估价","ar":"التوجيه إلى تقييم عقاري مرخّص من SPK عند اللزوم"},"Ücretsiz ön değerleme":{"en":"Free preliminary valuation","ru":"Бесплатная предварительная оценка","zh":"免费初步估值","ar":"تقييم مبدئي مجاني"},"SPK yönlendirme":{"en":"SPK referral","ru":"Направление к SPK","zh":"SPK 引荐","ar":"التوجيه إلى SPK"},"Ön ekspertiz ile SPK ekspertizi farkı ne?":{"en":"What is the difference between a preliminary appraisal and an SPK appraisal?","ru":"В чём разница между предварительной оценкой и оценкой SPK?","zh":"初步估价与 SPK 估价有何区别？","ar":"ما الفرق بين التقييم العقاري المبدئي وتقييم SPK؟"},"Ön ekspertiz, hızlı ve ücretsiz bir piyasa değer aralığıdır; SPK lisanslı ekspertiz ise resmi işlemlerde geçerli, lisanslı kurumca hazırlanan yasal rapordur.":{"en":"A preliminary appraisal is a fast, free market value range; an SPK-licensed appraisal is a legal report prepared by a licensed firm and valid for official transactions.","ru":"Предварительная оценка — это быстрый и бесплатный диапазон рыночной стоимости; лицензированная SPK оценка — это юридический отчёт, действительный в официальных процедурах и подготовленный лицензированной организацией.","zh":"初步估价是一份快速而免费的市场价值区间；SPK 持牌估价则是在正式手续中有效、由持牌机构出具的法定报告。","ar":"التقييم العقاري المبدئي نطاق قيمة سوقية سريع ومجاني؛ أما التقييم العقاري المرخّص من SPK فتقرير قانوني معتمد في المعاملات الرسمية تُعدّه جهة مرخّصة."},"Yatırım":{"en":"Investment","ru":"Инвестиции","zh":"投资","ar":"الاستثمار"},"Kira çarpanı, net ROI ve amortisman süresiyle veri odaklı yatırım kararları aldırırım.":{"en":"I guide data-driven investment decisions with rent multiplier, net ROI, and payback period.","ru":"Помогаю принимать инвестиционные решения на основе данных — с учётом арендного мультипликатора, чистого ROI и срока окупаемости.","zh":"凭借租金倍数、净投资回报率与回本周期，助您做出数据驱动的投资决策。","ar":"أُساعدك على اتخاذ قرارات استثمارية قائمة على البيانات بمضاعف الإيجار وصافي العائد على الاستثمار وفترة الاسترداد."},"Kira çarpanı — gayrimenkulün fiyatının yıllık brüt kira gelirine oranıdır — ve net getiri hesabıyla duygusal değil rakamsal karar verirsiniz. ProX yatırım skoru ve prim potansiyeliyle hangi bölgenin ne zaman kazandıracağını gösteririm.":{"en":"The rent multiplier — the ratio of a property's price to its annual gross rental income — and a net return calculation let you decide by numbers, not emotion. With the ProX investment score and appreciation potential, I show which area will pay off and when.","ru":"Арендный мультипликатор — это отношение цены объекта к годовому валовому арендному доходу — и с расчётом чистой доходности вы принимаете решение по цифрам, а не по эмоциям. На основе инвестиционного балла ProX и потенциала прироста стоимости показываю, какой район и когда принесёт прибыль.","zh":"凭借租金倍数——即房产价格与年度毛租金收入之比——与净收益测算，您将以数字而非感性做出决策。通过 ProX 投资评分与增值潜力，为您呈现哪个区域何时获益。","ar":"مضاعف الإيجار — وهو نسبة سعر العقار إلى دخل الإيجار السنوي الإجمالي — وحساب صافي العائد يجعلانك تقرّر بالأرقام لا بالعاطفة. وأُظهِر لك أيّ منطقة تُربِح ومتى، بتقييم استثمار ProX وإمكانات ارتفاع القيمة."},"Bütçe & risk profili belirleme":{"en":"Defining budget & risk profile","ru":"Определение бюджета и профиля риска","zh":"确定预算与风险特征","ar":"تحديد الميزانية وملفّ المخاطر"},"ProX yatırım skoru & prim analizi":{"en":"ProX investment score & appreciation analysis","ru":"Инвестиционный балл ProX и анализ прироста стоимости","zh":"ProX 投资评分与增值分析","ar":"تقييم استثمار ProX وتحليل ارتفاع القيمة"},"Kira çarpanı, net ROI & amortisman":{"en":"Rent multiplier, net ROI & payback period","ru":"Арендный мультипликатор, чистый ROI и срок окупаемости","zh":"租金倍数、净投资回报率与回本周期","ar":"مضاعف الإيجار وصافي العائد وفترة الاسترداد"},"Portföy önerisi & giriş stratejisi":{"en":"Portfolio recommendation & entry strategy","ru":"Рекомендация по портфелю и стратегия входа","zh":"投资组合建议与入场策略","ar":"اقتراح المحفظة واستراتيجية الدخول"},"Net ROI hesabı":{"en":"Net ROI calculation","ru":"Расчёт чистого ROI","zh":"净投资回报率测算","ar":"حساب صافي العائد على الاستثمار"},"Prim potansiyeli":{"en":"Appreciation potential","ru":"Потенциал прироста стоимости","zh":"增值潜力","ar":"إمكانات ارتفاع القيمة"},"İyi bir kira getirisi yüzde kaçtır?":{"en":"What counts as a good rental yield?","ru":"Какова хорошая доходность от аренды в процентах?","zh":"多少的租金回报率算好？","ar":"ما نسبة عائد الإيجار الجيّد؟"},"Türkiye'de brüt kira getirisi tipik olarak %4–8 aralığındadır; net getiriyi vergi, aidat ve boşluk süresiyle birlikte hesaplayıp bölgeye göre yorumlarım.":{"en":"In Turkey, gross rental yield typically falls in the %4–8 range; I calculate the net yield together with tax, dues, and vacancy periods, and interpret it by location.","ru":"В Турции валовая арендная доходность обычно находится в диапазоне %4–8; чистую доходность я рассчитываю с учётом налогов, взносов и периодов простоя и интерпретирую по району.","zh":"在土耳其，毛租金回报率通常在 %4–8 区间；我会将税费、物业费与空置期一并计入净收益，并结合区域加以解读。","ar":"يتراوح عائد الإيجار الإجمالي في تركيا عادةً بين %4–8؛ أحسب صافي العائد مع الضريبة ورسوم الإدارة ومدة الشغور وأُفسّره بحسب المنطقة."},"Endeks & Analiz":{"en":"Index & Analysis","ru":"Индекс и анализ","zh":"指数与分析","ar":"المؤشر والتحليل"},"Canlı ProX m² endeksiyle hangi bölgenin ne zaman değerlendiğini gösteririm.":{"en":"With the live ProX m² index, I show which area is appreciating and when.","ru":"На основе живого индекса ProX за м² показываю, какой район и когда растёт в цене.","zh":"凭借实时 ProX 每平方米指数，为您呈现哪个区域何时增值。","ar":"أُظهِر أيّ منطقة ترتفع قيمتها ومتى، بمؤشر ProX الحي لسعر المتر المربع."},"Mahalle bazlı m² değeri, 12 aylık fiyat seyri, yatırım skoru ve likidite; kararınızı trendle destekler. Bebek, Etiler, Zekeriyaköy, Kandilli gibi hatlarda gerçek endeks verisiyle doğru zamanı ve doğru semti birlikte belirleriz.":{"en":"Neighborhood-level m² value, 12-month price trajectory, investment score, and liquidity back your decision with the trend. Along lines such as Bebek, Etiler, Zekeriyaköy, and Kandilli, we determine the right time and the right district together with real index data.","ru":"Стоимость за м² по районам, ценовая динамика за 12 месяцев, инвестиционный балл и ликвидность подкрепляют ваше решение трендом. По таким направлениям, как Bebek, Etiler, Zekeriyaköy, Kandilli, мы совместно определяем правильное время и правильный район на основе реальных данных индекса.","zh":"按社区划分的每平方米价值、12 个月价格走势、投资评分与流动性，以趋势支撑您的决策。在 Bebek、Etiler、Zekeriyaköy、Kandilli 等地段，凭借真实指数数据，共同确定恰当的时机与合适的片区。","ar":"قيمة المتر المربع على مستوى الحي، ومسار الأسعار خلال 12 شهراً، وتقييم الاستثمار، والسيولة؛ كلّها تدعم قرارك بالاتجاه العام. نحدّد معاً الوقت المناسب والحيّ المناسب ببيانات مؤشر حقيقية على خطوط مثل Bebek وEtiler وZekeriyaköy وKandilli."},"Hedef bölge & mahalle seçimi":{"en":"Target area & neighborhood selection","ru":"Выбор целевого района и квартала","zh":"目标区域与社区选择","ar":"اختيار المنطقة والحي المستهدفَين"},"ProX 12 aylık trend & skor":{"en":"ProX 12-month trend & score","ru":"12-месячный тренд и балл ProX","zh":"ProX 12 个月趋势与评分","ar":"اتجاه ProX خلال 12 شهراً والتقييم"},"Karşılaştırmalı m² & likidite":{"en":"Comparative m² & liquidity","ru":"Сравнительный анализ за м² и ликвидность","zh":"每平方米对比与流动性","ar":"مقارنة سعر المتر المربع والسيولة"},"Giriş/çıkış zamanlaması önerisi":{"en":"Entry/exit timing recommendation","ru":"Рекомендация по времени входа/выхода","zh":"入场/退场时机建议","ar":"اقتراح توقيت الدخول/الخروج"},"Canlı ProX endeks":{"en":"Live ProX index","ru":"Живой индекс ProX","zh":"实时 ProX 指数","ar":"مؤشر ProX الحي"},"Mahalle bazlı":{"en":"Neighborhood-level","ru":"По районам","zh":"按社区划分","ar":"على مستوى الحي"},"Veriler ne kadar güncel?":{"en":"How current is the data?","ru":"Насколько актуальны данные?","zh":"数据有多新？","ar":"ما مدى حداثة البيانات؟"},"ProX bölge endeksi güncel piyasa verisiyle beslenir; ana sayfadaki Bölge Analizi panelinden mahalle bazlı canlı değerleri anlık görebilirsiniz.":{"en":"The ProX regional index is fed by current market data; you can view live neighborhood-level values in real time from the Region Analysis panel on the homepage.","ru":"Региональный индекс ProX питается актуальными рыночными данными; живые значения по районам вы можете видеть в реальном времени на панели «Анализ региона» на главной странице.","zh":"ProX 区域指数由最新市场数据驱动；您可在主页的区域分析面板中实时查看按社区划分的即时数值。","ar":"يُغذّى مؤشر منطقة ProX ببيانات السوق الحديثة؛ ويمكنك رؤية القيم الحية على مستوى الحي لحظياً من لوحة تحليل المنطقة في الصفحة الرئيسية."},"Tapu & Hukuk":{"en":"Title Deed & Law","ru":"Тапу и право","zh":"房产证与法律","ar":"سند الملكية والقانون"},"Tapu & Hukuki Süreç Danışmanlığı":{"en":"Title Deed & Legal Process Advisory","ru":"Консультирование по тапу и юридическому процессу","zh":"房产证与法律流程咨询","ar":"استشارة سند الملكية والإجراءات القانونية"},"Web Tapu başvurusundan devir randevusuna kadar tüm süreci hatasız yürütürüm.":{"en":"I conduct the entire process flawlessly, from the Web Tapu application to the transfer appointment.","ru":"Безошибочно веду весь процесс — от заявки в «Web Tapu» до записи на переоформление.","zh":"从 \"Web Tapu\" 申请到过户预约，无差错地推进整个流程。","ar":"أُدير العملية كاملةً دون خطأ، من طلب \"Web Tapu\" إلى موعد نقل الملكية."},"TKGM Web Tapu ve e-Devlet adımlarını, harç hesabını ve muhasebe kalemlerini eksiksiz koordine ederim. Böylece geri dönüş, eksik belge veya harç hatası riski olmadan devir gününe hazır olursunuz.":{"en":"I fully coordinate the TKGM Web Tapu and e-Devlet steps, the fee calculation, and the accounting items. This way, you are ready for transfer day without the risk of rejection, missing documents, or fee errors.","ru":"Полностью координирую шаги TKGM «Web Tapu» и e-Devlet, расчёт пошлины и бухгалтерские позиции. Так вы будете готовы ко дню переоформления без риска возврата, недостающих документов или ошибки в пошлине.","zh":"完整协调 TKGM \"Web Tapu\" 与 e-Devlet 各环节、税费测算与账务项目。如此，您将毫无退件、缺件或税费差错之虞地为过户日做好准备。","ar":"أُنسّق بالكامل خطوات TKGM و\"Web Tapu\" وe-Devlet وحساب الرسوم والبنود المحاسبية. بذلك تكون جاهزاً ليوم نقل الملكية دون مخاطر الردّ أو نقص المستندات أو خطأ الرسوم."},"Tapu kaydı & takyidat kontrolü":{"en":"Title deed record & encumbrances check","ru":"Проверка записи тапу и обременений","zh":"房产证登记与他项权利核查","ar":"التحقّق من قيد سند الملكية والقيود"},"Web Tapu / e-Devlet başvuru":{"en":"Web Tapu / e-Devlet application","ru":"Заявка в «Web Tapu» / e-Devlet","zh":"\"Web Tapu\" / e-Devlet 申请","ar":"طلب Web Tapu / e-Devlet"},"Harç & masraf hesabı":{"en":"Fee & cost calculation","ru":"Расчёт пошлины и расходов","zh":"税费与费用测算","ar":"حساب الرسوم والمصاريف"},"Devir randevusu & imza":{"en":"Transfer appointment & signing","ru":"Запись на переоформление и подписание","zh":"过户预约与签署","ar":"موعد نقل الملكية والتوقيع"},"Web Tapu":{"en":"Web Tapu","ru":"Web Tapu","zh":"Web Tapu","ar":"Web Tapu"},"Hatasız evrak":{"en":"Error-free paperwork","ru":"Безошибочные документы","zh":"无差错文件","ar":"مستندات دون أخطاء"},"Tapu harcı ne kadar?":{"en":"How much is the title deed fee?","ru":"Сколько составляет пошлина за тапу?","zh":"房产证过户税是多少？","ar":"كم يبلغ رسم سند الملكية؟"},"Tapu harcı satış bedeli üzerinden yasal oranla hesaplanır; güncel oranı işlem öncesi net olarak paylaşır, sürpriz masraf çıkmamasını sağlarım.":{"en":"The title deed fee is calculated at the statutory rate on the sale price; I share the current rate clearly before the transaction, ensuring no surprise costs arise.","ru":"Пошлина за тапу рассчитывается по установленной законом ставке от суммы продажи; актуальную ставку я чётко сообщаю до сделки и гарантирую отсутствие неожиданных расходов.","zh":"房产证过户税按销售金额以法定比率计算；我会在办理前明确告知现行比率，确保不出现意外费用。","ar":"يُحسَب رسم سند الملكية بالنسبة القانونية على بدل البيع؛ أُشارك النسبة الحالية بوضوح قبل المعاملة وأضمن عدم ظهور مصاريف مفاجئة."},"Finansman":{"en":"Financing","ru":"Финансирование","zh":"融资","ar":"التمويل"},"Konut Kredisi & Ödeme Planı Danışmanlığı":{"en":"Mortgage & Payment Plan Advisory","ru":"Консультирование по ипотеке и плану платежей","zh":"住房贷款与还款计划咨询","ar":"استشارة قرض السكن وخطة السداد"},"En uygun kredi yapısını kurgular, ekspertiz ve süreci hızlandırırım.":{"en":"I structure the most suitable loan and accelerate the appraisal and process.","ru":"Выстраиваю наиболее выгодную структуру кредита, ускоряю оценку и процесс.","zh":"构建最优贷款方案，加快估价与整个流程。","ar":"أُصمّم البنية الائتمانية الأنسب وأُسرّع التقييم العقاري والعملية."},"Banka faizlerini, ekspertiz koşullarını ve ödeme planlarını karşılaştırır; uygunsanız İlk Evim gibi avantajlı seçenekleri değerlendiririm. Onay sürecini takip eder, satın almanın finans ayağını kusursuz kılarım.":{"en":"I compare bank interest rates, appraisal conditions, and payment plans; if you are eligible, I explore advantageous options such as İlk Evim. I follow the approval process and make the financing side of the purchase seamless.","ru":"Сравниваю банковские ставки, условия оценки и планы платежей; если вы подходите, рассматриваю выгодные варианты, такие как «İlk Evim». Отслеживаю процесс одобрения и делаю финансовую часть покупки безупречной.","zh":"比较银行利率、估价条件与还款计划；若您符合条件，则评估 \"İlk Evim\" 等优惠方案。跟踪审批流程，让购买的融资环节尽善尽美。","ar":"أُقارن فوائد البنوك وشروط التقييم العقاري وخطط السداد؛ وإن كنت مؤهّلاً أُقيّم خيارات مميّزة مثل \"İlk Evim\". أتابع عملية الموافقة وأجعل الشقّ المالي من الشراء لا تشوبه شائبة."},"Bütçe & uygunluk değerlendirme":{"en":"Budget & eligibility assessment","ru":"Оценка бюджета и соответствия требованиям","zh":"预算与资格评估","ar":"تقييم الميزانية والأهلية"},"Banka faizi & ödeme planı kıyası":{"en":"Bank interest & payment plan comparison","ru":"Сравнение банковских ставок и планов платежей","zh":"银行利率与还款计划对比","ar":"مقارنة فائدة البنك وخطة السداد"},"Ekspertiz koordinasyonu":{"en":"Appraisal coordination","ru":"Координация оценки","zh":"估价协调","ar":"تنسيق التقييم العقاري"},"Onay takibi & kapanış":{"en":"Approval tracking & closing","ru":"Отслеживание одобрения и закрытие сделки","zh":"审批跟踪与交割","ar":"متابعة الموافقة والإغلاق"},"Faiz kıyaslama":{"en":"Interest comparison","ru":"Сравнение ставок","zh":"利率对比","ar":"مقارنة الفائدة"},"Hızlı onay takibi":{"en":"Fast approval tracking","ru":"Быстрое отслеживание одобрения","zh":"快速审批跟踪","ar":"متابعة موافقة سريعة"},"Kredi ekspertizini siz mi ayarlıyorsunuz?":{"en":"Do you arrange the loan appraisal?","ru":"Оценку для кредита организуете вы?","zh":"贷款估价由您安排吗？","ar":"هل تتولّون أنتم ترتيب التقييم العقاري للقرض؟"},"Evet; bankanın anlaşmalı ekspertiz sürecini koordine eder, değer ve kredi tutarının uyumlu çıkması için gerekli hazırlığı yaparım.":{"en":"Yes; I coordinate the bank's contracted appraisal process and make the necessary preparations so that the value and loan amount align.","ru":"Да; я координирую процесс оценки с банком-партнёром и провожу необходимую подготовку, чтобы стоимость и сумма кредита совпали.","zh":"是的；我会协调银行合作的估价流程，并为价值与贷款额度相匹配做好必要准备。","ar":"نعم؛ أُنسّق عملية التقييم العقاري المتعاقد عليها مع البنك، وأُجري الإعداد اللازم ليتوافق التقييم مع مبلغ القرض."},"Birden fazla gayrimenkulün getirisini tek elden, veriyle optimize ederim.":{"en":"I optimize the return of multiple properties from a single point, with data.","ru":"Оптимизирую доходность нескольких объектов недвижимости из одних рук, на основе данных.","zh":"统一以数据优化多处房产的收益。","ar":"أُحسّن عائد عدة عقارات من جهة واحدة وبالبيانات."},"Kira, bakım, vergi ve değer takibini tek panelden yönetir; hangi gayrimenkulün elde tutulacağını, hangisinin değerlendirileceğini ProX verisiyle raporlarım. Portföyünüz büyürken karmaşa değil, netlik kazanır.":{"en":"I manage rent, maintenance, tax, and value tracking from a single panel; with ProX data, I report which property to hold and which to divest. As your portfolio grows, it gains clarity, not chaos.","ru":"Управляю арендой, обслуживанием, налогами и отслеживанием стоимости с единой панели; на основе данных ProX отчитываюсь, какой объект удерживать, а какой реализовать. По мере роста ваш портфель обретает не хаос, а ясность.","zh":"在单一面板中管理租金、维护、税务与价值跟踪；凭借 ProX 数据向您呈报哪处房产应持有、哪处应处置。当您的投资组合壮大时，收获的是清晰而非混乱。","ar":"أُدير من لوحة واحدة متابعة الإيجار والصيانة والضريبة والقيمة؛ وأُقدّم تقريراً ببيانات ProX عن أيّ عقار يُحتفَظ به وأيّها يُثمَّن. تكسب محفظتك وضوحاً لا فوضى مع نموّها."},"Portföy envanteri & değer haritası":{"en":"Portfolio inventory & value map","ru":"Инвентаризация портфеля и карта стоимости","zh":"投资组合清单与价值地图","ar":"جرد المحفظة وخريطة القيمة"},"Kira, bakım & vergi takibi":{"en":"Rent, maintenance & tax tracking","ru":"Отслеживание аренды, обслуживания и налогов","zh":"租金、维护与税务跟踪","ar":"متابعة الإيجار والصيانة والضريبة"},"Tut / sat / dönüştür kararı analizi":{"en":"Hold / sell / convert decision analysis","ru":"Анализ решения удержать / продать / преобразовать","zh":"持有 / 出售 / 转换决策分析","ar":"تحليل قرار الاحتفاظ / البيع / التحويل"},"Periyodik performans raporu":{"en":"Periodic performance report","ru":"Периодический отчёт о результатах","zh":"定期业绩报告","ar":"تقرير أداء دوري"},"Tek elden yönetim":{"en":"Single-point management","ru":"Управление из одних рук","zh":"一站式管理","ar":"إدارة من جهة واحدة"},"Değer takibi":{"en":"Value tracking","ru":"Отслеживание стоимости","zh":"价值跟踪","ar":"متابعة القيمة"},"Kaç gayrimenkulten sonra yönetim gerekir?":{"en":"After how many properties is management needed?","ru":"Со скольких объектов необходимо управление?","zh":"拥有几处房产后才需要专业管理？","ar":"بعد كم عقار تصبح الإدارة ضرورية؟"},"Genellikle 2–3 gayrimenkulten sonra takip zorlaşır; ancak tek bir yüksek değerli gayrimenkulte bile kira, bakım ve değer optimizasyonu ciddi fark yaratır.":{"en":"Tracking usually becomes difficult after 2–3 properties; yet even for a single high-value property, rent, maintenance, and value optimization make a significant difference.","ru":"Обычно контроль усложняется после 2–3 объектов; однако даже для одного объекта высокой стоимости оптимизация аренды, обслуживания и стоимости даёт существенную разницу.","zh":"通常在 2–3 处房产之后跟踪便趋于困难；然而即便只有一处高价值房产，对租金、维护与价值的优化也能带来显著差异。","ar":"عادةً تصبح المتابعة صعبة بعد 2–3 عقارات؛ لكن حتى لعقار واحد مرتفع القيمة، يُحدث تحسين الإيجار والصيانة والقيمة فرقاً كبيراً."},"Satışa Hazırlık":{"en":"Sale Preparation","ru":"Подготовка к продаже","zh":"售前准备","ar":"الإعداد للبيع"},"Doğru sunumla gayrimenkulünüzü daha hızlı ve daha yüksek fiyata satılır kılarım.":{"en":"With the right presentation, I make your property sell faster and at a higher price.","ru":"С помощью правильной презентации делаю вашу недвижимость продаваемой быстрее и по более высокой цене.","zh":"以恰当的呈现，让您的房产更快、以更高价格售出。","ar":"أجعل عقارك قابلاً للبيع بشكل أسرع وبسعر أعلى بالعرض الصحيح."},"Alıcı kararını çoğu zaman sokakta değil, ekranda verir. Profesyonel fotoğraf, sadeleştirme ve sahneleme ile ilk izlenimi güçlendirir; ilan tıklama ve gösterim dönüşümünüzü artırırım.":{"en":"Buyers often decide not on the street but on the screen. With professional photography, decluttering, and staging, I strengthen the first impression and boost your listing's click-through and viewing conversion.","ru":"Покупатель чаще всего принимает решение не на улице, а на экране. С помощью профессиональной фотографии, разгрузки пространства и стейджинга усиливаю первое впечатление и повышаю конверсию кликов по объявлению и показов.","zh":"买家往往不是在街头，而是在屏幕前做出决定。凭借专业摄影、精简与场景布置强化第一印象；提升您的房源点击与看房转化。","ar":"غالباً ما يتّخذ المشتري قراره على الشاشة لا في الشارع. أُقوّي الانطباع الأول بالتصوير الاحترافي والتبسيط والتهيئة؛ وأرفع نقرات الإعلان ومعدّل تحويل المعاينات."},"Mekan denetimi & sadeleştirme":{"en":"Space review & decluttering","ru":"Проверка помещения и разгрузка пространства","zh":"空间检视与精简","ar":"تدقيق المكان وتبسيطه"},"Profesyonel görsel & sunum dosyası":{"en":"Professional imagery & presentation file","ru":"Профессиональные фото и презентационный файл","zh":"专业影像与展示文件","ar":"صور احترافية وملفّ عرض"},"İlan başlığı & metin optimizasyonu":{"en":"Listing title & copy optimization","ru":"Оптимизация заголовка и текста объявления","zh":"房源标题与文案优化","ar":"تحسين عنوان الإعلان ونصّه"},"Gösterim & geri bildirim yönetimi":{"en":"Viewing & feedback management","ru":"Управление показами и обратной связью","zh":"看房与反馈管理","ar":"إدارة المعاينات والتغذية الراجعة"},"Profesyonel görsel":{"en":"Professional imagery","ru":"Профессиональные фото","zh":"专业影像","ar":"صور احترافية"},"Hızlı satış":{"en":"Fast sale","ru":"Быстрая продажа","zh":"快速售出","ar":"بيع سريع"},"Home staging maliyeti değer mi?":{"en":"Is the cost of home staging worth it?","ru":"Стоит ли того стоимость хоум-стейджинга?","zh":"房屋美化的成本值得吗？","ar":"هل تكلفة تهيئة المنزل للبيع تستحق؟"},"Genellikle evet; iyi sahnelenmiş gayrimenkuller daha kısa sürede ve daha yüksek fiyata satılır, bu da hazırlık maliyetini fazlasıyla karşılar.":{"en":"Usually yes; well-staged properties sell in less time and at a higher price, which more than covers the preparation cost.","ru":"Как правило, да; хорошо оформленная недвижимость продаётся быстрее и дороже, что с лихвой окупает затраты на подготовку.","zh":"通常值得；精心布置的房产能在更短时间内以更高价格售出，足以覆盖并超出准备成本。","ar":"غالباً نعم؛ تُباع العقارات المُهيّأة جيداً في وقت أقصر وبسعر أعلى، ما يغطّي تكلفة الإعداد بأكثر من كافٍ."},"Kentsel Dönüşüm":{"en":"Urban Transformation","ru":"Городская трансформация","zh":"城市更新","ar":"التحول العمراني"},"Kentsel Dönüşüm & Yeni Proje Danışmanlığı":{"en":"Urban Transformation & New Development Advisory","ru":"Консультирование по городской трансформации и новым проектам","zh":"城市更新与新项目咨询","ar":"استشارة التحول العمراني والمشاريع الجديدة"},"Riskli yapı tespitinden hak sahipliğine kadar dönüşümde yanınızdayım.":{"en":"I stand by you in transformation, from risk-bearing building assessment to entitlement rights.","ru":"Я рядом с вами в реновации — от признания здания аварийным до установления прав собственников.","zh":"从危房认定到权属确认，在更新过程中始终相伴。","ar":"أقف إلى جانبك في التحول، من تحديد المبنى المعرّض للخطر إلى استحقاق الحقوق."},"6306 sayılı yasa kapsamında riskli yapı tespiti, hak sahipliği ve müteahhitle sözleşme adilliğini birlikte yönetiriz. Devlet destekleri ve kira yardımı süreçlerini takip eder, hakkınızı koruyan bir dönüşüm sağlarım.":{"en":"Under Law No. 6306, we manage together the risk-bearing building assessment, entitlement rights, and the fairness of the contract with the contractor. I follow the state incentives and rental assistance processes, ensuring a transformation that protects your rights.","ru":"В рамках закона 6306 мы совместно ведём признание здания аварийным, установление прав собственников и справедливость договора с застройщиком. Отслеживаю государственную поддержку и процессы помощи в аренде, обеспечивая реновацию, защищающую ваши права.","zh":"在 6306 号法律框架下，共同管理危房认定、权属确认与承包商合同的公平性。跟踪政府补贴与租金补助流程，为您实现一次维护权益的更新。","ar":"نُدير معاً، في نطاق القانون رقم 6306، تحديد المبنى المعرّض للخطر واستحقاق الحقوق وعدالة العقد مع المقاول. أتابع عمليات الدعم الحكومي ومساعدة الإيجار وأضمن تحوّلاً يحمي حقّك."},"Riskli yapı tespiti (6306)":{"en":"Risk-bearing building assessment (6306)","ru":"Признание здания аварийным (6306)","zh":"危房认定（6306）","ar":"تحديد المبنى المعرّض للخطر (6306)"},"Hak sahipliği & pay analizi":{"en":"Entitlement rights & share analysis","ru":"Установление прав собственников и анализ долей","zh":"权属确认与份额分析","ar":"استحقاق الحقوق وتحليل الحصص"},"Müteahhit sözleşmesi denetimi":{"en":"Contractor agreement review","ru":"Проверка договора с застройщиком","zh":"承包商合同审查","ar":"تدقيق عقد المقاول"},"Devlet desteği & kira yardımı takibi":{"en":"State incentive & rental assistance tracking","ru":"Отслеживание государственной поддержки и помощи в аренде","zh":"政府补贴与租金补助跟踪","ar":"متابعة الدعم الحكومي ومساعدة الإيجار"},"Sözleşme adilliği":{"en":"Contract fairness","ru":"Справедливость договора","zh":"合同公平性","ar":"عدالة العقد"},"Hak koruma":{"en":"Rights protection","ru":"Защита прав","zh":"权益保护","ar":"حماية الحقوق"},"Dönüşümde en büyük risk nedir?":{"en":"What is the biggest risk in transformation?","ru":"В чём наибольший риск при реновации?","zh":"更新中最大的风险是什么？","ar":"ما أكبر خطر في التحول العمراني؟"},"Genellikle müteahhit sözleşmesindeki pay ve teslim koşullarıdır; sözleşmeyi hak sahibinin lehine, teminatlı ve net biçimde kurgulamak kritik önemdedir.":{"en":"It is usually the share and delivery terms in the contractor agreement; structuring the contract in the owner's favor, with guarantees and in clear terms, is critically important.","ru":"Обычно это доли и условия сдачи в договоре с застройщиком; критически важно составить договор в пользу собственника — с гарантиями и чёткими формулировками.","zh":"通常是承包商合同中的份额与交付条件；以有利于权利人、有担保且清晰的方式拟定合同至关重要。","ar":"غالباً شروط الحصص والتسليم في عقد المقاول؛ ومن الحاسم صياغة العقد لصالح صاحب الحقّ، مضموناً وواضحاً."},"Yabancı Yatırımcı":{"en":"Foreign Investor","ru":"Иностранный инвестор","zh":"外籍投资者","ar":"المستثمر الأجنبي"},"Yabancıya Satış & Oturma İzni Gayrimenkulü":{"en":"Sale to Foreigners & Residence Permit Real Estate","ru":"Недвижимость для продажи иностранцам и ВНЖ","zh":"面向外籍人士销售与居留许可房产","ar":"عقارات البيع للأجانب وتصريح الإقامة"},"Yabancı yatırımcıya döviz bozdurmadan vatandaşlığa uyumlu, uçtan uca süreç.":{"en":"An end-to-end process tailored to the foreign investor, from currency exchange to citizenship.","ru":"Процесс под ключ для иностранного инвестора, согласованный от справки об обмене валюты до гражданства.","zh":"为外籍投资者提供从外汇兑换到公民身份合规的全流程服务。","ar":"عملية متكاملة من البداية إلى النهاية للمستثمر الأجنبي، من صرف العملة إلى الجنسية."},"Döviz bozdurma belgesi, değerleme raporu ve tapu şerhi gibi mevzuat adımlarını eksiksiz yönetir; vatandaşlık veya oturma izni hedefine uygun gayrimenkulleri seçerim. Yabancı alıcı için Türkiye'de güvenli bir gayrimenkul deneyimi sunarım.":{"en":"I fully manage the regulatory steps such as the currency exchange certificate, valuation report, and title deed annotation; I select properties suited to your citizenship or residence permit goal. For the foreign buyer, I offer a secure real estate experience in Turkey.","ru":"Полностью веду шаги по требованиям законодательства — справка об обмене валюты, отчёт об оценке стоимости и отметка в тапу; подбираю объекты, соответствующие цели гражданства или ВНЖ. Обеспечиваю иностранному покупателю безопасный опыт работы с недвижимостью в Турции.","zh":"完整办理外汇兑换证明、估值报告与房产证批注等法规环节；为您甄选契合公民身份或居留许可目标的房产。为外籍买家提供在土耳其安心的房地产体验。","ar":"أُدير بالكامل خطوات التشريع كشهادة صرف العملة وتقرير التقييم وشرح سند الملكية؛ وأختار العقارات المناسبة لهدف الجنسية أو تصريح الإقامة. أُقدّم للمشتري الأجنبي تجربة عقارية آمنة في تركيا."},"Uygunluk & hedef (oturma / vatandaşlık)":{"en":"Eligibility & goal (residence / citizenship)","ru":"Соответствие требованиям и цель (ВНЖ / гражданство)","zh":"资格与目标（居留 / 公民身份）","ar":"الأهلية والهدف (الإقامة / الجنسية)"},"Döviz bozdurma & değerleme raporu":{"en":"Currency exchange certificate & valuation report","ru":"Справка об обмене валюты и отчёт об оценке стоимости","zh":"外汇兑换证明与估值报告","ar":"صرف العملة وتقرير التقييم"},"Tapu şerhi & mevzuat uyumu":{"en":"Title deed annotation & regulatory compliance","ru":"Отметка в тапу и соответствие законодательству","zh":"房产证批注与法规合规","ar":"شرح سند الملكية والامتثال التشريعي"},"Başvuru dosyası koordinasyonu":{"en":"Application file coordination","ru":"Координация пакета документов для заявления","zh":"申请材料协调","ar":"تنسيق ملفّ الطلب"},"Mevzuat uyumu":{"en":"Regulatory compliance","ru":"Соответствие законодательству","zh":"法规合规","ar":"الامتثال التشريعي"},"Vatandaşlık desteği":{"en":"Citizenship support","ru":"Поддержка в получении гражданства","zh":"公民身份支持","ar":"دعم الجنسية"},"Vatandaşlık için gereken tutar nedir?":{"en":"What amount is required for citizenship?","ru":"Какая сумма требуется для гражданства?","zh":"取得公民身份所需金额是多少？","ar":"ما المبلغ المطلوب للحصول على الجنسية؟"},"Eşik değer mevzuatla belirlenir ve güncellenir; işlem öncesi geçerli tutarı ve satışta tapuya konan devir kısıtı şerhini net olarak paylaşırım.":{"en":"The threshold value is set and updated by regulation; before the transaction I clearly share the current amount and the transfer-restriction annotation placed on the title deed at sale.","ru":"Пороговое значение устанавливается и обновляется законодательством; до сделки я чётко сообщаю действующую сумму и отметку об ограничении на переоформление, вносимую в тапу при продаже.","zh":"门槛金额由法规确定并适时更新；我会在办理前明确告知现行金额，以及销售时在房产证上加注的转让限制批注。","ar":"تُحدَّد القيمة العتبية وتُحدَّث بالتشريع؛ أُشارك بوضوح قبل المعاملة المبلغَ المعمول به وشرحَ قيد نقل الملكية المدوَّن في سند الملكية عند البيع."},"Özel Segment":{"en":"Exclusive Segment","ru":"Особый сегмент","zh":"高端专属","ar":"الشريحة الخاصة"},"Boğaz & Yalı · Özel Segment Danışmanlığı":{"en":"Bosphorus & Yalı · Exclusive Segment Advisory","ru":"Консультирование по особому сегменту · Босфор и ялы","zh":"博斯普鲁斯与博斯普鲁斯海滨豪宅 · 高端专属咨询","ar":"استشارة البوسفور والقصور المائية · الشريحة الخاصة"},"Boğaz hattı yalı, penthouse ve özel segmentte davet usulü, tam gizlilikli temsil.":{"en":"By-invitation, fully confidential representation for Bosphorus-line waterfront mansions (yalı), penthouses, and the exclusive segment.","ru":"Полностью конфиденциальное представительство по приглашению для ялы на Босфоре, пентхаусов и объектов особого сегмента.","zh":"在博斯普鲁斯沿岸海滨豪宅、顶层公寓及高端专属领域，提供邀请制、完全保密的代理。","ar":"تمثيل بالدعوة وبسرّية تامة في قصور البوسفور المائية والبنتهاوس والشريحة الخاصة."},"En üst segment gayrimenkullerde ilan panolarına açılmadan; yalnızca önceden değerlendirilmiş, alım kapasitesi teyit edilmiş alıcı havuzuna sunum yaparım. Adres ve kimlik gizliliği esastır; prim potansiyeli ve nadirlik değeri özenle korunur.":{"en":"For top-tier properties, without ever going to listing boards, I present only to a pre-vetted buyer pool whose purchasing capacity has been confirmed. Address and identity privacy is paramount; appreciation potential and rarity value are carefully preserved.","ru":"В недвижимости высшего сегмента я не выхожу на доски объявлений — представляю объект только заранее оценённому пулу покупателей с подтверждённой платёжеспособностью. Конфиденциальность адреса и личности — основа; потенциал прироста стоимости и ценность редкости бережно сохраняются.","zh":"在最高端房产领域，不公开挂牌；仅向经预先评估、购买能力已核实的买家池呈现。地址与身份保密为本；增值潜力与稀缺价值得到悉心守护。","ar":"في عقارات الشريحة العليا، أعرض دون النشر على لوحات الإعلانات؛ حصراً على مجموعة مشترين مُقيَّمين مسبقاً ومؤكَّدة قدرتهم الشرائية. سرّية العنوان والهوية أساس؛ وتُصان إمكانات ارتفاع القيمة وقيمة النُدرة بعناية."},"Mahremiyet & davet usulü strateji":{"en":"Privacy & by-invitation strategy","ru":"Конфиденциальность и стратегия по приглашению","zh":"隐私与邀请制策略","ar":"الخصوصية واستراتيجية الدعوة"},"Seçili alıcı havuzu eşleştirme":{"en":"Select buyer pool matching","ru":"Подбор из отобранного пула покупателей","zh":"甄选买家池匹配","ar":"مطابقة مجموعة مشترين مختارة"},"Özel sunum & mahremiyet protokolü":{"en":"Private presentation & privacy protocol","ru":"Приватная презентация и протокол конфиденциальности","zh":"专属呈现与隐私协议","ar":"عرض خاص وبروتوكول خصوصية"},"Müzakere & kusursuz kapanış":{"en":"Negotiation & flawless closing","ru":"Переговоры и безупречное закрытие сделки","zh":"谈判与无懈可击的交割","ar":"تفاوض وإغلاق لا تشوبه شائبة"},"Davet usulü":{"en":"By invitation","ru":"По приглашению","zh":"邀请制","ar":"بالدعوة"},"Adresim gizli mi kalır?":{"en":"Will my address stay private?","ru":"Останется ли мой адрес конфиденциальным?","zh":"我的地址会保密吗？","ar":"هل يبقى عنواني سرّياً؟"},"Evet; özel segmentte yalnızca cadde/sokak ve başlangıç değeri paylaşılır, tam adres ve kimlik yalnızca ön değerlendirmeyi geçen ciddi alıcıyla, onayınızla açıklanır.":{"en":"Yes; in the exclusive segment only the avenue/street and starting value are shared, and the full address and identity are disclosed only to a serious buyer who has passed the pre-assessment, with your consent.","ru":"Да; в особом сегменте раскрываются только улица и начальная стоимость, а полный адрес и личность сообщаются только серьёзному покупателю, прошедшему предварительную оценку, и с вашего согласия.","zh":"会的；在高端专属领域仅披露街道与起始价值，完整地址与身份仅在您授权后向通过预先评估的诚意买家披露。","ar":"نعم؛ في الشريحة الخاصة لا يُشارَك سوى الجادّة/الشارع والقيمة الابتدائية، ولا يُكشَف العنوان الكامل والهوية إلا للمشتري الجادّ الذي اجتاز التقييم المسبق، وبموافقتك."},"Özel Masa · Miras & İntikal":{"en":"Dedicated Desk · Inheritance & Transfer","ru":"Особая служба · Наследство и оформление наследства","zh":"专属席 · 继承与继承过户","ar":"طاولة خاصة · الإرث ونقل الإرث"},"Miras kalan gayrimenkulü,":{"en":"Inherited property,","ru":"Унаследованную недвижимость","zh":"让继承所得的房产，","ar":"العقار الموروث،"},"hak kaybı yaşamadan":{"en":"without any loss of rights","ru":"примите","zh":"在不损失权益的前提下","ar":"دون فقدان أيّ حقّ"},"devralın.":{"en":"take it over.","ru":"без потери прав.","zh":"顺利承接。","ar":"تسلّمه."},"Miras kalan bir gayrimenkul; duygusal değerinin yanında çoğu zaman birden fazla mirasçıyı, karmaşık hukuki süreçleri ve sıkı vergi takvimlerini içeren teknik bir dosyaya dönüşür.":{"en":"An inherited property — alongside its sentimental value — often becomes a technical case involving multiple heirs, complex legal processes, and strict tax timelines.","ru":"Унаследованная недвижимость помимо своей эмоциональной ценности чаще всего превращается в техническое дело, охватывающее нескольких наследников, сложные юридические процедуры и строгие налоговые сроки.","zh":"一处继承所得的房产，除情感价值之外，往往会演变为一份涉及多位继承人、复杂法律流程与严格税务时限的技术性档案。","ar":"غالباً ما يتحوّل العقار الموروث، إلى جانب قيمته العاطفية، إلى ملفّ تقني يضمّ عدة ورثة وإجراءات قانونية معقّدة وجداول ضريبية صارمة."},"Yaklaşımım veri odaklıdır: taşınmazın güncel rayiç değerini bölge analizleriyle belirler, hisse yapısını ve mirasçı sayısını netleştirir; satış mı yoksa mirasçılar arası pay birleştirmesi mi daha verimli sonuç verir sorusunu rakamlarla ortaya koyarım.":{"en":"My approach is data-driven: I determine the property's current market value through regional analysis, clarify the share structure and the number of heirs, and answer with numbers the question of whether a sale or a consolidation of shares among the heirs yields the more efficient outcome.","ru":"Мой подход основан на данных: я определяю актуальную рыночную стоимость объекта через анализ региона, проясняю структуру долей и число наследников; вопрос о том, что эффективнее — продажа или объединение долей между наследниками, — я представляю в цифрах.","zh":"我的方式是数据驱动的：通过区域分析确定不动产的现行市场价值，厘清份额结构与继承人数量；以数字揭示出售还是继承人之间份额合并更为有效的答案。","ar":"نهجي قائم على البيانات: أحدّد القيمة السوقية الحالية للعقار بتحليلات المنطقة، وأُوضّح بنية الحصص وعدد الورثة؛ وأُبيّن بالأرقام أيّهما يحقّق نتيجة أجدى: البيع أم دمج الحصص بين الورثة."},"Vergi oran ve süreleri her yıl güncellenir; işlemler öncesi güncel mevzuata göre birlikte planlarız. Bu içerik bilgilendirme amaçlıdır, hukuki danışmanlık yerine geçmez.":{"en":"Tax rates and deadlines are updated every year; before any transaction we plan together according to the current regulations. This content is for informational purposes and does not substitute for legal advice.","ru":"Налоговые ставки и сроки обновляются ежегодно; до совершения операций мы планируем совместно в соответствии с действующим законодательством. Этот материал носит информационный характер и не заменяет юридическую консультацию.","zh":"税率与时限每年更新；办理前我们会依据现行法规共同规划。本内容仅供参考，不构成法律咨询。","ar":"تُحدَّث نسب الضرائب ومددها كل عام؛ نُخطّط معاً قبل المعاملات وفق التشريعات الحالية. هذا المحتوى لغرض الإعلام ولا يحلّ محلّ الاستشارة القانونية."},"01 · Veraset İlamı":{"en":"01 · Certificate of Inheritance","ru":"01 · Свидетельство о наследстве","zh":"01 · 继承裁定书","ar":"01 · حجّة الوراثة"},"Sulh hukuk mahkemesi veya noterden veraset belgesi.":{"en":"Certificate of inheritance from the civil court of peace or a notary.","ru":"Свидетельство о наследстве от мирового суда или нотариуса.","zh":"由初级民事法院或公证处出具的继承证明。","ar":"وثيقة الوراثة من محكمة الصلح المدنية أو الكاتب بالعدل."},"02 · Mirasçı Belgeleme":{"en":"02 · Documenting the Heirs","ru":"02 · Документирование наследников","zh":"02 · 继承人认定","ar":"02 · توثيق الورثة"},"Tüm mirasçıların ve pay oranlarının tespiti.":{"en":"Identification of all heirs and their share proportions.","ru":"Установление всех наследников и их долей.","zh":"确定全体继承人及各自份额比例。","ar":"تحديد جميع الورثة ونسب حصصهم."},"03 · Rayiç Değer Tespiti":{"en":"03 · Market Value Assessment","ru":"03 · Определение рыночной стоимости","zh":"03 · 市场价值认定","ar":"03 · تحديد القيمة السوقية"},"ProX bölge verisiyle güncel piyasa değeri.":{"en":"Current market value with ProX regional data.","ru":"Актуальная рыночная стоимость по региональным данным ProX.","zh":"凭借 ProX 区域数据确定现行市场价值。","ar":"القيمة السوقية الحالية ببيانات منطقة ProX."},"04 · Hisse & Pay Dağılımı":{"en":"04 · Share & Interest Distribution","ru":"04 · Распределение долей","zh":"04 · 份额分配","ar":"04 · توزيع الحصص والأنصبة"},"Satış mı, pay birleştirme mi — rakamsal analiz.":{"en":"Sale or share consolidation — a numerical analysis.","ru":"Продажа или объединение долей — числовой анализ.","zh":"出售还是份额合并——以数字分析。","ar":"بيع أم دمج حصص — تحليل رقمي."},"05 · Tapuda İntikal":{"en":"05 · Transfer at the Land Registry","ru":"05 · Оформление наследства на тапу","zh":"05 · 房产证继承过户","ar":"05 · نقل الإرث في سند الملكية"},"İntikal başvurusu ve tapu devir işlemleri.":{"en":"Transfer application and title deed transfer procedures.","ru":"Заявление на оформление наследства и переоформление тапу.","zh":"继承过户申请与房产证过户手续。","ar":"طلب نقل الإرث ومعاملات نقل سند الملكية."},"06 · Veraset & İntikal Vergisi":{"en":"06 · Inheritance & Transfer Tax","ru":"06 · Налог на наследство и оформление наследства","zh":"06 · 继承与继承过户税","ar":"06 · ضريبة الإرث ونقل الإرث"},"Beyan, taksitlendirme ve süre yönetimi.":{"en":"Declaration, installment arrangement, and deadline management.","ru":"Декларирование, рассрочка и управление сроками.","zh":"申报、分期与时限管理。","ar":"الإقرار والتقسيط وإدارة المدة."},"Rakamlarla":{"en":"In Numbers","ru":"В цифрах","zh":"以数字见证","ar":"بالأرقام"},"Deneyim ve güvenin karşılığı":{"en":"The measure of experience and trust","ru":"Итог опыта и доверия","zh":"经验与信任的回报","ar":"ثمرة الخبرة والثقة"},",4 Mr ₺":{"en":"₺,4B","ru":",4 млрд ₺","zh":",4 Mr ₺","ar":",4 مليار ₺"},"Hangi hizmete ihtiyacınız olduğundan emin değil misiniz?":{"en":"Not sure which service you need?","ru":"Не уверены, какая услуга вам нужна?","zh":"不确定自己需要哪项服务？","ar":"ألستَ متأكداً من الخدمة التي تحتاجها؟"},"Bağlayıcı olmayan, gizli bir ön görüşmeyle başlayalım; ihtiyacınızı birlikte netleştirip doğru yol haritasını çıkaralım.":{"en":"Let's begin with a non-binding, confidential preliminary consultation; together we'll clarify your needs and map out the right path.","ru":"Начнём с ни к чему не обязывающей, конфиденциальной предварительной встречи; вместе проясним вашу потребность и составим правильную дорожную карту.","zh":"让我们从一次无约束、保密的初步沟通开始；共同厘清您的需求，规划正确的路线图。","ar":"لنبدأ بلقاء تمهيدي سرّي وغير مُلزِم؛ نُوضّح معاً احتياجك ونرسم خارطة الطريق الصحيحة."},"Ücretsiz Görüşme":{"en":"Free Consultation","ru":"Бесплатная консультация","zh":"免费沟通","ar":"لقاء مجاني"},"WhatsApp'tan Yaz":{"en":"Message on WhatsApp","ru":"Написать в WhatsApp","zh":"通过 WhatsApp 联系","ar":"راسِلني عبر WhatsApp"},"Hizmetlerimiz — Lüks Konut, Değerleme, Yatırım · Selin Meridyen":{"en":"Our Services — Luxury Residential, Valuation, Investment · Selin Meridyen","ru":"Наши услуги — элитная недвижимость, оценка стоимости, инвестиции · Selin Meridyen","zh":"我们的服务 — 豪华住宅、估值、投资 · Selin Meridyen","ar":"خدماتنا — سكن فاخر، تقييم، استثمار · Selin Meridyen"},"İstanbul'da lüks konut alım-satımı, davet usulü satış, ücretsiz değerleme, yatırım analizi, kiralama, tapu-hukuk ve miras. Canlı ProX verisiyle danışmanlık.":{"en":"Luxury residential buying and selling in İstanbul, by-invitation sales, free valuation, investment analysis, leasing, title-deed and legal matters, and inheritance. Advisory with live ProX data.","ru":"Купля-продажа элитной недвижимости в Стамбуле, продажа по приглашению, бесплатная оценка стоимости, инвестиционный анализ, аренда, тапу-право и наследство. Консультирование на живых данных ProX.","zh":"在伊斯坦布尔提供豪华住宅买卖、邀请制销售、免费估值、投资分析、租赁、房产证-法律及继承服务。凭借实时 ProX 数据的咨询。","ar":"بيع وشراء السكن الفاخر في إسطنبول، والبيع بالدعوة، والتقييم المجاني، وتحليل الاستثمار، والتأجير، وسند الملكية والقانون، والإرث. استشارة ببيانات ProX الحية."},"Hizmetlerimiz — Lüks Konut, Değerleme, Yatırım, Kiralama ve Miras · Selin Meridyen":{"en":"Our Services — Luxury Residential, Valuation, Investment, Leasing, and Inheritance · Selin Meridyen","ru":"Наши услуги — элитная недвижимость, оценка стоимости, инвестиции, аренда и наследство · Selin Meridyen","zh":"我们的服务 — 豪华住宅、估值、投资、租赁与继承 · Selin Meridyen","ar":"خدماتنا — سكن فاخر، تقييم، استثمار، تأجير وإرث · Selin Meridyen"},"İstanbul'da uçtan uca, kişiye özel lüks gayrimenkul danışmanlığı: alım-satım, değerleme, yatırım analizi, kiralama, tapu-hukuk, kentsel dönüşüm, yabancıya satış ve miras/intikal — canlı ProX bölge verisiyle.":{"en":"End-to-end, tailored luxury real estate advisory in İstanbul: buying and selling, valuation, investment analysis, leasing, title-deed and legal matters, urban transformation, sale to foreigners, and inheritance transfer — with live ProX regional data.","ru":"Индивидуальное консультирование по элитной недвижимости под ключ в Стамбуле: купля-продажа, оценка стоимости, инвестиционный анализ, аренда, тапу-право, городская трансформация, продажа иностранцам и наследство/оформление наследства — на живых региональных данных ProX.","zh":"在伊斯坦布尔提供全流程、私人定制的豪华房地产咨询：买卖、估值、投资分析、租赁、房产证-法律、城市更新、面向外籍人士销售及继承/继承过户——凭借实时 ProX 区域数据。","ar":"استشارة عقارية فاخرة مخصّصة ومتكاملة في إسطنبول: بيع وشراء، تقييم، تحليل استثمار، تأجير، سند الملكية والقانون، تحوّل عمراني، بيع للأجانب وإرث/نقل إرث — ببيانات منطقة ProX الحية."},"Aracılık Edilen Değer":{"en":"Value Brokered","ru":"Стоимость проведённых сделок","zh":"已促成交易价值","ar":"قيمة تمّت الوساطة فيها"},"Yetki Belgeli Portföy":{"en":"Certified Portfolio","ru":"Лицензированный портфель","zh":"持证房源","ar":"محفظة بشهادة تفويض"}};